1	<!DOCTYPE html>
2	<html lang="zh-Hant-TW">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
6	<title>中華網紅協會 CICA｜台灣網紅・KOL・創作者的全國性協會</title>
7	<meta name="description" content="中華網紅協會 CICA，2020 年立案的全國性人民團體。攜手臺北網紅節與 TY Star 臺北網紅獎，串聯商圈、品牌與台越跨境商機，為台灣網紅、KOL 與自媒體創作者打造更高曝光、更多交流、更多商機、更廣串聯的舞台。">
8	<meta name="keywords" content="中華網紅協會,CICA,網紅協會,KOL,臺北網紅節,TY Star 臺北網紅獎,鄭儷絲,網紅經濟,創作者">
9	<meta name="theme-color" content="#08070C">
10	<meta property="og:type" content="website">
11	<meta property="og:locale" content="zh_TW">
12	<meta property="og:site_name" content="中華網紅協會 CICA">
13	<meta property="og:title" content="中華網紅協會 CICA｜台灣網紅・KOL・創作者的全國性協會">
14	<meta property="og:description" content="更高曝光・更多交流・更多商機・更廣串聯。網紅不是年輕人的專利。">
15	<meta property="og:image" content="assets/photos/ty2025-open.jpg">
16	<meta name="twitter:card" content="summary_large_image">
17	<link rel="preconnect" href="https://fonts.googleapis.com">
18	<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
19	<link href="https://fonts.googleapis.com/css2?family=Noto+Sans+TC:wght@400;500;600;700;900&family=Noto+Serif+TC:wght@700;900&family=Space+Grotesk:wght@500;600;700&display=swap" rel="stylesheet">
20	<link rel="icon" href="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'%3E%3Cdefs%3E%3ClinearGradient id='g' x1='0' y1='0' x2='1' y2='1'%3E%3Cstop offset='0' stop-color='%23FF4FA3'/%3E%3Cstop offset='.5' stop-color='%23A98CFF'/%3E%3Cstop offset='1' stop-color='%234EDDF5'/%3E%3C/linearGradient%3E%3C/defs%3E%3Crect width='32' height='32' rx='9' fill='%2308070C'/%3E%3Ctext x='16' y='23.5' font-family='Helvetica,Arial,sans-serif' font-size='19' font-weight='700' text-anchor='middle' fill='url(%23g)'%3EC%3C/text%3E%3C/svg%3E">
21	<style>
22	:root{
23	  --ink:#08070C; --ink2:#0C0A13; --ink3:#131020;
24	  --tx:#F3F1F8; --tx2:#D6D1E4; --tx3:#BDB7CE;
25	  --line:rgba(255,255,255,.14); --line2:rgba(255,255,255,.08);
26	  --mag:#FF4FA3; --vio:#A98CFF; --cyn:#4EDDF5;
27	  --grad:linear-gradient(100deg,#FF4FA3 0%,#A98CFF 52%,#4EDDF5 100%);
28	  --sans:"Noto Sans TC",system-ui,-apple-system,"PingFang TC","Microsoft JhengHei",sans-serif;
29	  --serif:"Noto Serif TC",Georgia,serif;
30	  --disp:"Space Grotesk","Noto Sans TC",system-ui,sans-serif;
31	  --nav-h:78px; --pad:clamp(20px,5vw,64px); --maxw:1300px; --r:20px;
32	  --ease:cubic-bezier(.22,.61,.36,1);
33	}
34	*{box-sizing:border-box}
35	html{-webkit-text-size-adjust:100%;scroll-behavior:smooth}
36	body{margin:0;background:var(--ink);color:var(--tx);font-family:var(--sans);
37	  font-size:20px;line-height:1.85;font-weight:400;overflow-x:hidden;
38	  -webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility}
39	img{max-width:100%;display:block;height:auto}
40	a{color:inherit}
41	button{font:inherit;color:inherit;background:none;border:0;cursor:pointer}
42	h1,h2,h3,h4{margin:0;line-height:1.22;font-weight:900;letter-spacing:-.01em}
43	p{margin:0}
44	ul,ol{margin:0;padding:0;list-style:none}
45	figure{margin:0}
46	::selection{background:var(--mag);color:#fff}
47	:focus-visible{outline:3px solid var(--cyn);outline-offset:3px;border-radius:6px}
48	
49	.wrap{width:min(100%,var(--maxw));margin-inline:auto;padding-inline:var(--pad)}
50	section{position:relative}
51	.sec{padding-block:clamp(72px,10vw,132px);scroll-margin-top:calc(var(--nav-h) + 12px)}
52	.eyebrow{font-family:var(--disp);font-size:19px;font-weight:700;letter-spacing:.24em;
53	  text-transform:uppercase;color:var(--cyn);margin-bottom:18px;display:block}
54	.sec-h{font-size:clamp(38px,5.4vw,68px);margin-bottom:20px}
55	.sec-lead{font-size:clamp(20px,2vw,23px);color:var(--tx2);max-width:60ch;line-height:1.8}
56	.grad{background:var(--grad);-webkit-background-clip:text;background-clip:text;color:transparent}
57	.hr{height:1px;background:linear-gradient(90deg,transparent,var(--line),transparent);border:0;margin:0}
58	
59	/* ---------- nav ---------- */
60	#nav{position:fixed;inset:0 0 auto 0;z-index:90;height:var(--nav-h);
61	  background:rgba(8,7,12,.72);backdrop-filter:blur(18px);
62	  border-bottom:1px solid var(--line2);transition:background .3s}
63	#nav.solid{background:rgba(8,7,12,.94)}
64	.nav-in{height:100%;display:flex;align-items:center;justify-content:space-between;gap:20px}
65	.brand{display:flex;align-items:center;gap:13px;text-decoration:none;font-weight:900}
66	.brand-mark{width:42px;height:42px;border-radius:12px;background:var(--grad);
67	  display:grid;place-items:center;color:#0A0810;font-family:var(--disp);font-size:21px;font-weight:700;flex:none}
68	.brand-tx{font-size:22px;letter-spacing:.01em;white-space:nowrap}
69	.brand-tx i{display:block;font-style:normal;font-family:var(--disp);font-size:18px;
70	  font-weight:600;letter-spacing:.2em;color:var(--tx3)}
71	.nav-links{display:flex;align-items:center;gap:clamp(14px,1.7vw,28px)}
72	.nav-links a{font-size:19px;font-weight:500;text-decoration:none;color:var(--tx2);
73	  padding:8px 2px;position:relative;transition:color .2s;white-space:nowrap}
74	.nav-links a::after{content:"";position:absolute;left:0;right:100%;bottom:2px;height:2px;
75	  background:var(--grad);transition:right .28s var(--ease)}
76	.nav-links a:hover{color:#fff}
77	.nav-links a:hover::after{right:0}
78	.nav-cta{font-size:19px;font-weight:700;text-decoration:none;padding:12px 22px;border-radius:999px;
79	  background:var(--grad);color:#0A0810;white-space:nowrap;transition:transform .2s,filter .2s}
80	.nav-cta:hover{transform:translateY(-2px);filter:brightness(1.08)}
81	#burger{display:none;width:52px;height:52px;border-radius:14px;border:1px solid var(--line);
82	  place-items:center;flex:none}
83	#burger span{display:block;width:24px;height:2px;background:#fff;position:relative}
84	#burger span::before,#burger span::after{content:"";position:absolute;left:0;width:24px;height:2px;background:#fff;transition:.25s}
85	#burger span::before{top:-8px}#burger span::after{top:8px}
86	#burger[aria-expanded="true"] span{background:transparent}
87	#burger[aria-expanded="true"] span::before{top:0;transform:rotate(45deg)}
88	#burger[aria-expanded="true"] span::after{top:0;transform:rotate(-45deg)}
89	#drawer{position:fixed;inset:var(--nav-h) 0 auto 0;z-index:89;background:rgba(10,8,16,.985);
90	  backdrop-filter:blur(20px);border-bottom:1px solid var(--line);padding:14px var(--pad) 30px;display:none}
91	#drawer.open{display:block}
92	#drawer a{display:block;font-size:21px;font-weight:600;text-decoration:none;padding:15px 0;
93	  border-bottom:1px solid var(--line2);color:var(--tx)}
94	#drawer .nav-cta{display:block;text-align:center;margin-top:20px;border-bottom:0}
95	
96	/* ---------- hero ---------- */
97	.hero{position:relative;min-height:min(100svh,940px);display:flex;align-items:flex-end;
98	  padding-top:calc(var(--nav-h) + 40px);padding-bottom:clamp(48px,7vw,90px);overflow:hidden}
99	.hero-bg{position:absolute;inset:0;z-index:0}
100	.hero-bg img{width:100%;height:100%;object-fit:cover;object-position:50% 42%;opacity:.42;filter:saturate(1.15)}
101	.hero-bg::after{content:"";position:absolute;inset:0;
102	  background:radial-gradient(120% 90% at 12% 8%,rgba(255,79,163,.30),transparent 55%),
103	             radial-gradient(110% 80% at 92% 22%,rgba(78,221,245,.24),transparent 55%),
104	             linear-gradient(180deg,rgba(8,7,12,.62) 0%,rgba(8,7,12,.80) 46%,var(--ink) 96%)}
105	.hero-in{position:relative;z-index:1;width:100%}
106	.hero-pill{display:inline-flex;align-items:center;gap:12px;font-size:22px;font-weight:600;
107	  padding:12px 24px;border-radius:999px;border:1px solid rgba(255,255,255,.24);
108	  background:rgba(255,255,255,.09);color:#fff;margin-bottom:26px;line-height:1.5}
109	.hero-pill b{color:var(--cyn);font-weight:800}
110	.dot{width:10px;height:10px;border-radius:50%;background:var(--mag);flex:none;
111	  box-shadow:0 0 0 6px rgba(255,79,163,.22)}
112	.hero h1{font-size:clamp(50px,10vw,132px);line-height:1.02;letter-spacing:-.03em;margin-bottom:8px}
113	.hero h1 span{display:block}
114	.hero-en{font-family:var(--disp);font-size:clamp(20px,2.6vw,30px);font-weight:700;
115	  letter-spacing:.3em;color:var(--tx2);margin:20px 0 26px;text-transform:uppercase}
116	.hero-lead{font-size:clamp(21px,2.2vw,26px);color:#EDEAF5;max-width:44ch;line-height:1.75;font-weight:400}
117	.hero-cta{display:flex;flex-wrap:wrap;gap:16px;margin-top:38px}
118	.btn{display:inline-flex;align-items:center;gap:11px;font-size:21px;font-weight:700;
119	  text-decoration:none;padding:18px 34px;border-radius:999px;transition:transform .22s var(--ease),filter .22s,background .22s}
120	.btn-p{background:var(--grad);color:#0A0810}
121	.btn-p:hover{transform:translateY(-3px);filter:brightness(1.09)}
122	.btn-g{border:1px solid rgba(255,255,255,.32);color:#fff;background:rgba(255,255,255,.06)}
123	.btn-g:hover{background:rgba(255,255,255,.14);transform:translateY(-3px)}
124	.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:clamp(14px,2vw,30px);
125	  margin-top:clamp(42px,6vw,72px);padding-top:34px;border-top:1px solid var(--line)}
126	.stat b{display:block;font-family:var(--disp);font-size:clamp(38px,5.4vw,62px);font-weight:700;
127	  line-height:1;background:var(--grad);-webkit-background-clip:text;background-clip:text;color:transparent}
128	.stat span{display:block;font-size:19px;color:var(--tx2);margin-top:10px;font-weight:500}
129	
130	/* ---------- statement ---------- */
131	.statement{padding-block:clamp(90px,13vw,170px);position:relative;overflow:hidden;
132	  background:linear-gradient(180deg,var(--ink) 0%,#120B1C 40%,#0E0A18 100%)}
133	.statement::before{content:"";position:absolute;inset:-30% -10% auto -10%;height:80%;
134	  background:radial-gradient(60% 60% at 50% 40%,rgba(255,79,163,.22),transparent 70%);filter:blur(30px)}
135	.st-in{position:relative;text-align:center}
136	.st-mark{font-family:var(--serif);font-size:clamp(72px,12vw,150px);line-height:.7;
137	  color:var(--mag);opacity:.55;display:block;margin-bottom:14px}
138	.st-quote{font-family:var(--serif);font-weight:900;font-size:clamp(40px,9.4vw,118px);
139	  line-height:1.12;letter-spacing:-.02em;color:#FFFFFF;
140	  text-shadow:0 0 44px rgba(255,79,163,.42),0 0 100px rgba(169,140,255,.24)}
141	.st-sub{font-size:clamp(22px,2.6vw,30px);font-weight:700;color:#E7DFF5;margin-top:30px}
142	.st-note{font-size:20px;color:var(--tx2);max-width:46ch;margin:20px auto 0;line-height:1.8}
143	.st-tags{display:flex;flex-wrap:wrap;gap:14px;justify-content:center;margin-top:34px}
144	.st-tags span{font-size:19px;font-weight:700;padding:11px 22px;border-radius:999px;
145	  border:1px solid rgba(255,79,163,.5);background:rgba(255,79,163,.14);color:#FFD9EC}
146	
147	/* ---------- mission ---------- */
148	.mission{display:grid;grid-template-columns:1fr 1fr;gap:16px 40px;margin-top:clamp(34px,4vw,52px)}
149	.mission li{display:grid;grid-template-columns:auto 1fr;gap:14px;align-items:start;
150	  font-size:20px;color:var(--tx2);line-height:1.8;padding:16px 0;border-top:1px solid var(--line2)}
151	.mission .mk{color:var(--mag);font-size:19px;line-height:1.9}
152	@media (max-width:900px){.mission{grid-template-columns:1fr;gap:0}}
153	
154	/* ---------- why ---------- */
155	.why-grid{display:grid;gap:22px;margin-top:clamp(40px,5vw,62px)}
156	.why-item{display:grid;grid-template-columns:auto 1fr;gap:clamp(20px,3vw,40px);
157	  align-items:start;padding:clamp(26px,3vw,40px);border-radius:var(--r);
158	  border:1px solid var(--line2);background:linear-gradient(160deg,rgba(255,255,255,.055),rgba(255,255,255,.018));
159	  transition:border-color .3s,transform .3s var(--ease),background .3s}
160	.why-item:hover{border-color:rgba(255,79,163,.45);transform:translateY(-4px);background:rgba(255,255,255,.06)}
161	.why-n{font-family:var(--disp);font-size:clamp(48px,6vw,76px);font-weight:700;line-height:.9;
162	  background:var(--grad);-webkit-background-clip:text;background-clip:text;color:transparent}
163	.why-item h3{font-size:clamp(26px,2.7vw,32px);margin-bottom:12px}
164	.why-item p{font-size:20px;color:var(--tx2);line-height:1.85}
165	
166	/* ---------- founder ---------- */
167	.fnd{display:grid;grid-template-columns:minmax(0,.85fr) minmax(0,1.15fr);
168	  gap:clamp(30px,4.5vw,64px);align-items:start;margin-top:clamp(36px,4vw,56px)}
169	.fnd-photo{position:relative;border-radius:26px;padding:6px;background:var(--grad);
170	  box-shadow:0 34px 90px rgba(255,79,163,.20)}
171	.fnd-photo img{border-radius:22px;width:100%;aspect-ratio:1/1;object-fit:cover}
172	.fnd-badge{position:absolute;left:50%;bottom:-26px;transform:translateX(-50%);
173	  background:#0C0A13;border:1px solid var(--line);border-radius:999px;padding:12px 24px;
174	  font-size:19px;font-weight:700;white-space:nowrap;box-shadow:0 12px 34px rgba(0,0,0,.5)}
175	.fnd-name{font-size:clamp(38px,4.6vw,58px);margin:52px 0 6px}
176	.fnd-role{font-size:22px;font-weight:700;color:var(--cyn);margin-bottom:22px}
177	.fnd-body p{font-size:20px;color:var(--tx2);line-height:1.9;margin-bottom:18px}
178	.fnd-tags{display:flex;flex-wrap:wrap;gap:11px;margin:22px 0 30px}
179	.fnd-tags span{font-size:18px;font-weight:600;padding:9px 17px;border-radius:10px;
180	  border:1px solid var(--line);background:rgba(255,255,255,.05);color:var(--tx2)}
181	.cv{border-top:1px solid var(--line2);margin-top:6px}
182	.cv li{display:grid;grid-template-columns:auto 1fr;gap:18px;padding:15px 0;
183	  border-bottom:1px solid var(--line2);font-size:19px;color:var(--tx2);align-items:baseline}
184	.cv li b{color:var(--mag);font-size:19px;font-family:var(--disp);font-weight:700;white-space:nowrap}
185	.bio-strip{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-top:34px}
186	.bio-strip figure{border-radius:14px;overflow:hidden;border:1px solid var(--line2);background:var(--ink3)}
187	.bio-strip img{aspect-ratio:4/5;object-fit:cover;width:100%;transition:transform .5s var(--ease)}
188	.bio-strip figure:hover img{transform:scale(1.06)}
189	.bio-strip figcaption{font-size:18px;color:var(--tx3);padding:12px 13px;line-height:1.5}
190	
191	/* ---------- socials ---------- */
192	.soc-wrap{margin-top:clamp(46px,6vw,80px);padding:clamp(28px,4vw,48px);border-radius:var(--r);
193	  border:1px solid var(--line);background:linear-gradient(160deg,rgba(255,255,255,.06),rgba(255,255,255,.02))}
194	.soc-h{font-size:clamp(26px,3vw,36px);margin-bottom:10px}
195	.soc-lead{font-size:20px;color:var(--tx2);margin-bottom:30px}
196	.soc-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}
197	.sbtn{display:flex;align-items:center;gap:16px;min-width:0;text-decoration:none;padding:18px 20px;
198	  border-radius:16px;border:1px solid var(--line);background:rgba(255,255,255,.045);
199	  min-height:96px;transition:transform .25s var(--ease),border-color .25s,background .25s}
200	.sbtn:hover{transform:translateY(-4px);background:rgba(255,255,255,.09)}
201	.sbtn-ico{width:56px;height:56px;flex:none;border-radius:14px;display:grid;place-items:center;
202	  background:rgba(255,255,255,.08)}
203	.sbtn-ico svg{width:34px;height:34px;fill:currentColor}
204	.sbtn-tx{min-width:0;overflow-wrap:anywhere}
205	.sbtn-tx b{display:block;font-size:20px;font-weight:700;color:#fff;line-height:1.35}
206	.sbtn-tx i{display:block;font-style:normal;font-size:18px;color:var(--tx3);line-height:1.45;margin-top:2px}
207	.wordmark{font-family:var(--disp);font-size:22px;font-weight:700;letter-spacing:.02em}
208	.s-fb .sbtn-ico{color:#fff;background:#1877F2}
209	.s-fb:hover{border-color:#1877F2}
210	.s-ig .sbtn-ico{color:#fff;background:linear-gradient(45deg,#F58529,#DD2A7B 45%,#8134AF 70%,#515BD4)}
211	.s-ig:hover{border-color:#DD2A7B}
212	.s-th .sbtn-ico{color:#0A0810;background:#fff}
213	.s-th:hover{border-color:#fff}
214	.s-tt .sbtn-ico{color:#fff;background:#000;position:relative;overflow:hidden}
215	.s-tt .sbtn-ico::before{content:"";position:absolute;inset:0;
216	  background:radial-gradient(circle at 30% 35%,rgba(37,244,238,.75),transparent 55%),
217	             radial-gradient(circle at 70% 65%,rgba(254,44,85,.75),transparent 55%)}
218	.s-tt .sbtn-ico svg{position:relative;z-index:1}
219	.s-tt:hover{border-color:#25F4EE}
220	.s-yt .sbtn-ico{color:#fff;background:#FF0000}
221	.s-yt:hover{border-color:#FF0000}
222	.s-yy .sbtn-ico{color:#0A0810;background:#FFCC00}
223	.s-yy:hover{border-color:#FFCC00}
224	.s-hy .sbtn-ico{color:#0A0810;background:#FF9500;font-size:19px}
225	.s-hy .wordmark{font-family:var(--sans);font-size:20px;font-weight:900}
226	.s-hy:hover{border-color:#FF9500}
227	
228	/* ---------- TY star ---------- */
229	.ty{background:linear-gradient(180deg,var(--ink) 0%,#0D0A16 100%)}
230	.ty-explain{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,.9fr);gap:clamp(26px,3.5vw,52px);
231	  align-items:center;padding:clamp(28px,4vw,50px);border-radius:26px;margin-top:clamp(34px,4vw,52px);
232	  border:1px solid rgba(78,221,245,.32);background:linear-gradient(150deg,rgba(78,221,245,.11),rgba(169,140,255,.07))}
233	.ty-kw{font-family:var(--disp);font-size:clamp(64px,10vw,130px);font-weight:700;line-height:.9;
234	  background:var(--grad);-webkit-background-clip:text;background-clip:text;color:transparent;margin-bottom:14px}
235	.ty-explain h3{font-size:clamp(26px,3vw,36px);margin-bottom:16px}
236	.ty-explain p{font-size:20px;color:var(--tx2);line-height:1.9;margin-bottom:14px}
237	.ty-explain p b{color:#fff}
238	.ty-fig img{border-radius:18px;width:100%;aspect-ratio:4/3;object-fit:cover;border:1px solid var(--line)}
239	.ty-fig figcaption{font-size:18px;color:var(--tx3);margin-top:12px;line-height:1.6}
240	.ty-correct{margin-top:24px;padding:20px 24px;border-radius:16px;border-left:4px solid var(--cyn);
241	  background:rgba(78,221,245,.10);font-size:19px;color:var(--tx2);line-height:1.8}
242	.ty-correct b{color:#fff}
243	.tiers{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:clamp(34px,4vw,52px)}
244	.tier{padding:30px 26px;border-radius:20px;border:1px solid var(--line);
245	  background:linear-gradient(160deg,rgba(255,255,255,.06),rgba(255,255,255,.02));transition:transform .3s var(--ease),border-color .3s}
246	.tier:hover{transform:translateY(-5px);border-color:rgba(255,79,163,.42)}
247	.tier .ic{font-size:44px;line-height:1;margin-bottom:14px}
248	.tier h4{font-size:26px;margin-bottom:8px}
249	.tier p{font-size:19px;color:var(--tx2);line-height:1.7}
